// Dashed round rect outline.
//
// Calculated distance along the edge of the rrect,
// calculated dash pattern along the edge,
// and substracts dash pattern from the outline.
//
// based on https://www.shadertoy.com/view/4llXD7

#define pi 3.14159267

// b.x = width
// b.y = height
// r.x = roundness top-right  
// r.y = roundness boottom-right
// r.z = roundness top-left
// r.w = roundness bottom-left
vec2 sdRoundBox( in vec2 p, in vec2 b, in vec4 r ) 
{
    vec4 rr = r;
    r.xy = (p.x>0.0)?r.xy : r.zw;
    r.x  = (p.y>0.0)?r.x  : r.y;
    vec2 q = abs(p)-b+r.x;
    float d = min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r.x;

    // quadrant lenghts
    vec4 qlen = 0.5 * pi * rr + (b.x + b.y) - rr * 2.;

    float len = 0.;

    // start length for each quadrant.
    if (p.y > 0.)
        len = (p.x > 0.) ? 0. : qlen.x + qlen.y + qlen.w;
    else
        len = (p.x > 0.) ? qlen.x : qlen.x + qlen.y;

    // TODO: There's quite obvious pattern left, but I was not able to simplify it.
    if (q.y > 0. && q.x > 0.) {
        // corner
        if (p.x * p.y > 0.) {
            len += b.x - r.x;
            len += (pi*0.5 - atan(q.y,q.x)) * r.x;
        } else {
            len += b.y - r.x;
            len += atan(q.y,q.x) * r.x;
        }
    } else if (q.x > q.y) {
        // left/right
        if (p.x * p.y > 0.) {
           len += b.x - r.x; // horiz
           len += (0.5 * pi * r.x); // corner
           len += (b.y - r.x) - abs(p.y);
        } else {
           len += abs(p.y); // left edge
        }
    } else {
        // top/bottom
        if (p.x * p.y > 0.) {
           len += abs(p.x);
        } else {
           len += b.y - r.x; // vert
           len += (0.5 * pi * r.x); // corner
           len += (b.x - r.x) - abs(p.x);
        }
    }

    return vec2(d, len);
}


float dashingDist(float t, float offset, float filled, float gap)
{
	float m1 = filled * 0.5;
	float m2 = gap * 0.5;
	// Here's where the magic happens
	t += offset;
	float s = mod(t + (filled + gap), filled + gap);

	if (s < filled)
		return abs(m1 - s) - m1;
	return m2 - abs(filled + m2 - s);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

	vec2 si = vec2(0.9,0.6) + 0.3*cos(iTime+vec2(0,2));
    vec4 ra = 0.3 + 0.3*cos( 2.0*iTime + vec4(0,1,2,3) );
    ra = min(ra,min(si.x,si.y));

	vec2 dr = sdRoundBox( p, si, ra );
    float d = dr.x;
    float len = dr.y;

    float filled = 0.1;
    float gap = 0.05;

/*
    // snap to full dash length
    vec4 qlen = 0.5 * pi * ra + (si.x + si.y) - ra * 2.;
    float full = qlen.x + qlen.y + qlen.z + qlen.w;
    float repeats = floor(full / (filled + gap)) * (filled + gap);
    len = gap*0.5 + len / full * repeats;
*/  

    float ddash = dashingDist(len, 0.0, filled, gap);

    d = max(abs(d) - 0.02, ddash);

    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp(-6.0*abs(d));
	col *= 0.8 + 0.2*cos(150.0*d);
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );


	fragColor = vec4(col,1.0);
}
